describe('Order Summary Before Payment Confirmation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="cart-items"]').should('exist');
  });

  it('should display order summary with all items and total before payment confirmation', () => {
    cy.get('[data-testid="order-summary"]').should('be.visible');

    cy.get('[data-testid="summary-items"]').within(() => {
      cy.get('[data-testid="item"]').should('have.length.greaterThan', 0);
      cy.get('[data-testid="item-name"]').first().should('not.be.empty');
      cy.get('[data-testid="item-price"]').first().should('not.be.empty');
      cy.get('[data-testid="item-quantity"]').first().should('not.be.empty');
    });

    cy.get('[data-testid="subtotal"]').should('be.visible').and('contain', '$');
    cy.get('[data-testid="tax"]').should('be.visible').and('contain', '$');
    cy.get('[data-testid="shipping"]').should('be.visible').and('contain', '$');
    cy.get('[data-testid="order-total"]').should('be.visible').and('contain', '$');

    cy.get('[data-testid="confirm-payment-btn"]').should('be.visible').and('not.be.disabled');
  });

  it('should handle empty order summary gracefully', () => {
    cy.intercept('GET', '/api/cart', { body: { items: [] } }).as('emptyCart');
    cy.reload();
    cy.wait('@emptyCart');

    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="empty-cart-message"]').should('be.visible').and('contain', 'Your cart is empty');
    cy.get('[data-testid="confirm-payment-btn"]').should('be.disabled');
  });

  it('should update order summary when item quantity changes', () => {
    cy.get('[data-testid="order-total"]').then(($total) => {
      const initialTotal = $total.text();

      cy.get('[data-testid="item-quantity-input"]').first().clear().type('2');
      cy.get('[data-testid="update-quantity-btn"]').click();

      cy.get('[data-testid="order-total"]').should('not.have.text', initialTotal);
      cy.get('[data-testid="order-total"]').invoke('text').then((newTotal) => {
        expect(newTotal).to.not.equal(initialTotal);
      });
    });
  });

  it('should display discount applied to order summary', () => {
    cy.get('[data-testid="promo-code-input"]').type('SAVE10');
    cy.get('[data-testid="apply-promo-btn"]').click();

    cy.get('[data-testid="discount"]').should('be.visible').and('contain', '-$');
    cy.get('[data-testid="order-total"]').should('be.visible');

    cy.get('[data-testid="subtotal"]').then(($subtotal) => {
      cy.get('[data-testid="discount"]').then(($discount) => {
        cy.get('[data-testid="order-total"]').then(($total) => {
          const subtotal = parseFloat($subtotal.text().replace('$', ''));
          const discount = parseFloat($discount.text().replace('-$', ''));
          const total = parseFloat($total.text().replace('$', ''));

          expect(total).to.be.closeTo(subtotal - discount, 0.01);
        });
      });
    });
  });
});
